    BR.put("skill:" + uk, "Mining:12,Farming:5")
    BR.put("quest:fn:hud", Fn(lambda o: OBJ(["The Farming Island", "1 / 3", "Talk to the Farmer", "0 / 1", JClass("java.lang.Double")(0.0), "", "", FALSE])))
    IC_.FIRE = Fire()
