    K.check(pk and all(("#SkyyInvBt%d" % k_) in [b_[1] for b_ in binds_of(pk[-1])] for k_ in range(4)), "CRAFT tabs: each bench tab is bound")
    shown = [str(x_) for x_ in pg.cshown if x_ is not None]
    seen = set(shown)
