    for iid_, ms_ in (("Armor_Iron_Chest", 1), ("Armor_Iron_Legs", 1), ("Ore_Copper", 100), ("Skyy_Ench_Iron", 100)):
        it_ = Ucls.allocateInstance(ITc.class_)
