    p_ = one(ev(PK, {"a": "kg", "SlotIndex": 0}), "REQ2 PICK the stored Lead pickaxe into Hotbar 4")
    K.check(MUT()[-1] == ("pick", 1, "7|e:eQ") and str(pg.mode) == "r", "REQ2 PICK an item in Requip storage = Requip's pick by its entry, nothing moves (%s)" % (MUT()[-1],))
    one(ev(PK, {"a": "rs:h", "SlotIndex": 3}), "REQ2 PICK Hotbar 4 again")
    one(ev(PK, {"a": "kk"}), "REQ2 KEEP Hotbar 4")
    # Hotbar 1 back on Auto (its list's Auto best): the best pickaxe at once
    one(ev(PK, {"a": "rs:h", "SlotIndex": 0}), "REQ2 PICK Hotbar 1")
    p_ = one(ev(PK, {"a": "ku"}), "REQ2 AUTO Hotbar 1")
    K.check(MUT()[-1] == ("pick", 1, "4|e:eQ") and (int(pv("p.1.hand")) & 16) == 0 and pv("p.1.last.4") == "Tool_Pickaxe_Lead_SkyWynn" and lab_(cmap(p_))[4] == "auto",
            "REQ2 AUTO Hotbar 1's Auto best: back on Auto, the T5 pickaxe set at once (%s %s)" % (MUT()[-1], dict(props_())))
    # Equip: every slot set by you stays; the Auto slot is already the best = Equip only
    m0_ = len(MUT())
    p_ = one(ev(PK, {"a": "rqeq"}), "REQ2 EQUIP Mining")
    K.check(MUT()[m0_:] == [("equip", 1, "")] and "Auto:" not in (sval(cmap(p_), "#SkyyInvRqI.Text") or ""),
            "REQ2 EQUIP every slot set by you stays, Hotbar 1 already the best -> Equip only (%s)" % MUT()[m0_:])
    m0_ = len(MUT())
    one(ev(PK, {"a": "rqeq"}), "REQ2 EQUIP again")
    K.eq(MUT()[m0_:], [("equip", 1, "")], "REQ2 EQUIP again: nothing left to change = only Equip")
    m0_ = len(MUT())
    one(ev(PK, {"a": "rp:1"}), "REQ2 EQUIP from the presets row")
    K.eq(MUT()[m0_:], [("equip", 1, "")], "REQ2 EQUIP the presets row runs Auto too (nothing to change here)")
    # Auto back on Head
    one(ev(PK, {"a": "rs:a", "SlotIndex": 0}), "REQ2 PICK Head")
    p_ = one(ev(PK, {"a": "ku"}), "REQ2 AUTO Head")
    cm = cmap(p_) if p_ else {}
    K.check(MUT()[-1] == ("pick", 1, "0|e:eL") and lab_(cm)[0] == "auto" and (int(pv("p.1.hand")) & 1) == 0 and pv("p.1.last.0") == "Armor_Mining_Lead_Head"
            and (sval(cm, "#SkyyInvRqI.Text") or "").startswith("Head is on Auto"), "REQ2 AUTO a slot's Auto: back on Auto, the best helmet set at once (%s %s %s %s)" % (sval(cm, "#SkyyInvRqI.Text"), MUT()[-3:], lab_(cm), dict(props_())))
    # Auto off / on (reset)
    p_ = one(ev(PK, {"a": "rqau"}), "REQ2 AUTO off")
    cm = cmap(p_) if p_ else {}
    K.check(pv("p.1.auto") == "0" and sval(cm, "#SkyyInvRqAu.Text") == "Auto Off" and "auto" not in lab_(cm) and "by you" not in lab_(cm), "REQ2 AUTO OFF: no auto / by you marks")
    m0_ = len(MUT())
    one(ev(PK, {"a": "rqeq"}), "REQ2 EQUIP with Auto off")
    K.eq(MUT()[m0_:], [("equip", 1, "")], "REQ2 EQUIP with Auto OFF = Equip only")
    pg.lastMove = ""
    p_ = one(ev(PK, {"a": "rqau"}), "REQ2 AUTO on")
    cm = cmap(p_) if p_ else {}
    K.check(pv("p.1.auto") == "1" and pv("p.1.hand") == "0" and lab_(cm)[:5] == ["auto", "auto", "auto", "auto", "auto"], "REQ2 AUTO ON again = every armour + tool slot back on Auto (%s)" % lab_(cm))
    m0_ = len(MUT())
    R2["eqfail"] = True
    p_ = one(ev(PK, {"a": "rqeq"}), "REQ2 EQUIP after the reset (Requip refuses the Equip)")
    R2["eqfail"] = False
    K.check(MUT()[m0_:] == [("drop", 1, "2|storage:3:Armor_Iron_Hands"), ("keep", 1, "3"), ("equip", 1, "")],
            "REQ2 EQUIP after the reset: the gloves from the bag (drop), the worn legs stay where they are (Keep), the rest already best (%s)" % MUT()[m0_:])
    t_ = sval(cmap(p_), "#SkyyInvRqI.Text") or ""
    K.check(t_.startswith("Mining is locked.") and "put 1 item from your bag into Requip storage" in t_ and "nothing is lost" in t_,
            "REQ2 FIX Equip refused after Auto moved gear = says the gear waits in Requip storage (%s)" % t_)
    m0_ = len(MUT())
    one(ev(PK, {"a": "rqeq"}), "REQ2 EQUIP once more")
    K.eq(MUT()[m0_:], [("equip", 1, "")], "REQ2 EQUIP once more: Auto has nothing left to do")
    # pets: the owned list, a pet, None, Keep; Auto refused
    p_ = one(ev(PK, {"a": "rs:a", "SlotIndex": 4}), "REQ2 PET slot")
    cm = cmap(p_) if p_ else {}
    K.check(str(pg.mode) == "k" and sval(cm, "#SkyyInvKT.Text") == "PICK PET - MINING" and "Skyy_PetIcon_Wolf_Legendary" in cm.get("#SkyyInvKg.Slots", "")
            and "Rare Wolf Lv 3" in cm.get("#SkyyInvKg.Slots", "") and sval(cm, "#SkyyInvKU.Text") == "No Auto", "REQ2 PET the pet list (icon, label, rarity colour)")
    one(ev(PK, {"a": "kg", "SlotIndex": 0}), "REQ2 PET pick the wolf")
    K.eq(MUT()[-1], ("pet", 1, "0|pA"), "REQ2 PET a pet = Requip's pet pick")
    one(ev(PK, {"a": "rs:a", "SlotIndex": 4}), "REQ2 PET slot again")
    one(ev(PK, {"a": "ke"}), "REQ2 PET Empty")
    K.eq(MUT()[-1], ("pet", 1, "0|"), "REQ2 PET Empty = none")
    one(ev(PK, {"a": "rs:a", "SlotIndex": 5}), "REQ2 MOUNT slot")
    one(ev(PK, {"a": "kk"}), "REQ2 MOUNT Keep")
    K.eq(MUT()[-1], ("pet", 1, "1|~"), "REQ2 MOUNT Keep = keep")
    one(ev(PK, {"a": "rs:a", "SlotIndex": 5}), "REQ2 MOUNT slot again")
    m0_ = len(MUT())
    p_ = one(ev(PK, {"a": "ku"}), "REQ2 MOUNT Auto")
    K.check(len(MUT()) == m0_ and sval(cmap(p_), "#SkyyInvKi.Text") == str(DATA.K_NOAUTO), "REQ2 MOUNT Auto = said, no call")
    # a profile switch between the draw and the click
    one(ev(PK, {"a": "rs:a", "SlotIndex": 0}), "REQ2 SAFE draw Head")
    BR.put("profile:fn:key", Fn(lambda u_: str(u_) + "-p2"))
    m0_ = len(MUT())
    p_ = one(ev(PK, {"a": "kg", "SlotIndex": 0}), "REQ2 SAFE click after a profile switch")
    K.check(len(MUT()) == m0_ and "profile changed" in (sval(cmap(p_), "#SkyyInvKi.Text") or ""), "REQ2 SAFE a profile switch between draw and click = said, NO call")
    BR.remove("profile:fn:key")
    one(ev(PK, {"a": "kb"}), "REQ2 Back")
    # a custom preset: everything that fits, no Auto
    p_ = one(ev(PK, {"a": "rl:5"}), "REQ2 CUSTOM Loadout 6")
    K.check(sval(cmap(p_), "#SkyyInvRqAu.Text") == "No Auto" and "auto" not in lab_(cmap(p_)), "REQ2 CUSTOM no Auto on a custom preset")
    p_ = one(ev(PK, {"a": "rs:a", "SlotIndex": 0}), "REQ2 CUSTOM Head")
    K.check("Armor_Cloth_Head" in shown_() and "Armor_Mining_Lead_Head" in shown_(), "REQ2 CUSTOM the list = every helmet that fits (%s)" % shown_())
    one(ev(PK, {"a": "kb"}), "REQ2 CUSTOM Back")
    p_ = one(ev(PK, {"a": "rqau"}), "REQ2 CUSTOM Auto")
    K.eq(sval(cmap(p_), "#SkyyInvRqI.Text"), str(DATA.RQ_NOAUTO), "REQ2 CUSTOM Auto = said")
    # SkyyWardrobe 0.2.15 (no cands / pick / pet, 4 preset fields): the picker says so, Auto does nothing
    R2["old"], R2["four"] = True, True
    one(ev(PK, {"a": "rl:1"}), "REQ2 OLD Mining")
    p_ = one(ev(PK, {"a": "rs:a", "SlotIndex": 0}), "REQ2 OLD Head")
    K.eq(sval(cmap(p_), "#SkyyInvKi.Text"), str(DATA.K_OLD), "REQ2 OLD the picker says it needs SkyyWardrobe 0.2.16")
    p_ = one(ev(PK, {"a": "ke"}), "REQ2 OLD Empty")
    K.eq(sval(cmap(p_), "#SkyyInvKi.Text"), str(DATA.K_OLD), "REQ2 OLD Empty = the same line (nothing changed)")
    one(ev(PK, {"a": "kb"}), "REQ2 OLD Back")
    m0_ = len(R2["calls"])
    p_ = one(ev(PK, {"a": "rqeq"}), "REQ2 OLD Equip")
    K.check(R2["calls"][m0_:] == [("equip", 1, "")] and "auto" not in lab_(cmap(p_)), "REQ2 OLD Equip = Equip only (no Auto, no read)")
    R2["old"], R2["four"] = False, False
    # the record survives a restart (read back from the file); FIX: an odd item id is escaped, not dropped
    odd_ = "Some Mod/Item=1 ü#x"
    props_().setProperty("p.1.last.9", odd_)
    K.check(bool(ST.rqSave(key_)), "REQ2 FIX save with an odd item id")
    h0_ = pv("p.1.hand")
    ST.RQA.clear()
    txt_ = open(os.path.join(rqdir_, key_ + ".properties"), encoding="utf8").read()
    K.check(pv("p.1.last.9") == odd_ and "p.1.last.9=Some\\u0020Mod\\u002fItem\\u003d1\\u0020\\u00fc\\u0023x" in txt_,
            "REQ2 FIX an item id outside [A-Za-z0-9:_.-] is kept (escaped) and reads back the same (%s)" % pv("p.1.last.9"))
    K.check(pv("p.1.hand") == h0_ and pv("p.1.auto") == "1" and "p.1.auto=1" in txt_ and txt_.startswith("# SkyyMenu: Requip Auto") and int(ST.RQSAVES) > 0
            and sorted(os.listdir(rqdir_)) == [key_ + ".properties"], "REQ2 FILE read back after a restart = the same record; one file per profile, nothing else")
    K.eq(E.count(PK, "Armor_Copper_Head"), cp0_ + 1, "REQ2 the page itself never moved an item")
    inv(PK, "storage").removeItemStackFromSlot(JShort(7))
    for k_ in ("requip:fn:presets", "requip:fn:preset", "requip:fn:act"):
        BR.put(k_, Fn(NEW[k_]))
    one(ev(PK, {"a": "rqd"}), "REQ2 Done")
    ST.RQA.clear()
    ST.RQDIR = None
    p_ = one(ev(PK, {"a": "pt:1"}), "INV4 the Mining pocket")
    cm = cmap(p_) if p_ else {}
    K.check(str(pg.mode) == "p" and sval(cm, "#SkyyInvPkT.Text") == "MINING POCKET" and sval(cm, "#SkyyInvPkL.Text") == "Lv 3  -  Rare  -  240 / 6,720"
            and "Ore_Copper" in cm.get("#SkyyInvPg.Slots", "") and "128" in cm.get("#SkyyInvPg.Slots", "") and "#SkyyInvCg.Slots" not in cm
            and TSEL_ in mk_of(p_, "SkyyInvPt1") and TSEL_ not in mk_of(p_, "SkyyInvPt0") and nometa(p_),
            "INV4 POCKET: the Mining grid with the real counts (the exact 128 in the name; the icon number a full stack at most), the level line, its tab selected (%s)" % sval(cm, "#SkyyInvPkL.Text"))
    K.check("Gone_Mod_Item" not in cm.get("#SkyyInvPg.Slots", "") and "Gone Mod Item  -  7 in the Void" in cm.get("#SkyyInvPg.Slots", "") and str(pg.pkey) == "k1",
            "INV4 FIX an id the server does not know = a name-only slot, never an ItemStack; the list's profile token kept")
    p_ = one(ev(PK, {"a": "pgs", "SlotIndex": 3}), "INV4 FIX pick the unknown item")
    K.check(str(pg.psel) == "Gone_Mod_Item" and "Gone_Mod_Item" not in cmap(p_).get("#SkyyInvPsl.Slots", "") and sval(cmap(p_), "#SkyyInvPsN.Text") == "Gone Mod Item",
            "INV4 FIX the picked unknown item: its name, no ItemStack in the pick slot")
    pg.psel = None
    p_ = one(ev(PK, {"a": "po:wd", "@A": "64"}), "INV4 Withdraw with nothing picked")
    K.check(POCK == [] and "Pick an item" in (sval(cmap(p_), "#SkyyInvPr.Text") or ""), "INV4 an action with nothing picked: no call")
    p_ = one(ev(PK, {"a": "pgs", "SlotIndex": 0}), "INV4 pick Copper Ore")
    K.check(str(pg.psel) == "Ore_Copper" and "128" in (sval(cmap(p_), "#SkyyInvPsC.Text") or "") and "5 each" in (sval(cmap(p_), "#SkyyInvPsC.Text") or ""),
            "INV4 the picked item: its Void count + the Bazaar price (%s)" % sval(cmap(p_), "#SkyyInvPsC.Text"))
    for op_, amt_ in (("wd", "64"), ("sell", "10"), ("unpack", "all")):   # 0.3.66: Deposit = FURN2 POCKET
        p_ = one(ev(PK, {"a": "po:" + op_, "@A": amt_}), "INV4 " + op_)
        K.check(POCK[-1] == (op_, "Ore_Copper", amt_) and PTOK[-1] == "k1" and sval(cmap(p_), "#SkyyInvPr.Text") == "Took 64 Copper Ore",
                "INV4 %s -> sacks:fn:pocket (%s, Ore_Copper, '%s'), its answer shown" % (op_, op_, amt_))
    # ---- FURN2 POCKET (0.3.66; Skyy 11-22 "the deposit button isnt working"): Deposit counts what you carry first
    PDF = {"full": None}

    def f_pdep(o):
        PTOK.append(str(o[4]) if len(o) > 4 else None)
        POCK.append((str(o[1]), str(o[2]), str(o[3])))
        if str(o[1]) != "dep":
            return "+Took 64 Copper Ore"
        if PDF["full"] == str(o[2]):
            return "-This category is full - level it up or upgrade its rarity"
        return "+Put %d %s into the Void" % (E.count(PK, str(o[2])), str(o[2]))
    BR.put("sacks:fn:pocket", Fn(f_pdep))
    BR.put("sacks:fn:catOf", Fn(lambda o: "Mining" if str(o) in ("Ore_Copper", "Skyy_Ench_Iron") else ("Farming" if str(o) == "Plant_Fruit_Apple" else None)))
    pr_ = lambda p_: sval(cmap(p_), "#SkyyInvPr.Text") or ""
    PDT = dict((k_, str(getattr(DATA, k_))) for k_ in ("PD_META", "PD_NONE", "PD_NONEP", "PD_OFFER", "PD_OFFERP"))
    fr_ = [i_ for i_ in range(36) if at(PK, "storage", i_) is None][:3]
    hf_ = [i_ for i_ in range(9) if at(PK, "hotbar", i_) is None][0]
    K.check(len(fr_) == 3 and E.count(PK, "Ore_Copper") == 0 and E.count(PK, "Skyy_Ench_Iron") == 0, "FURN2 POCKET the stand-in player carries no Mining item yet")
    n0_ = len(POCK)
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit, nothing of the pocket carried")
    K.check(len(POCK) == n0_ and pr_(p_) == PDT["PD_NONE"].replace("{C}", "Mining"), "FURN2 POCKET nothing carried = the reason, NO call (%s)" % pr_(p_))
    put(PK, "storage", fr_[0], ISc("Ore_Copper", 5))
    p_ = one(ev(PK, {"a": "po:dep", "@A": "2"}), "FURN2 POCKET Deposit the picked item")
    K.check(len(POCK) == n0_ + 1 and POCK[-1] == ("dep", "Ore_Copper", "2") and PTOK[-1] == "k1" and pr_(p_) == "Put 5 Ore_Copper into the Void",
            "FURN2 POCKET the picked item carried = ONE sacks:fn:pocket dep (the amount, the list's token), its answer shown (%s)" % pr_(p_))
    inv(PK, "storage").removeItemStackFromSlot(JShort(fr_[0]))
    put(PK, "storage", fr_[1], ISc("Skyy_Ench_Iron", 4))
    put(PK, "hotbar", hf_, ISc("Skyy_Ench_Iron", 2))
    put(PK, "storage", fr_[2], ISc("Plant_Fruit_Apple", 7))
    n0_ = len(POCK)
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit, the picked item not carried")
    K.check(len(POCK) == n0_ and pr_(p_) == PDT["PD_OFFER"].replace("{N}", "1").replace("{C}", "Mining") and int(pg.pdAt) > 0,
            "FURN2 POCKET the picked item not carried = a clear line offering the 1 other Mining item you carry (not the Farming apple), NO call (%s)" % pr_(p_))
    pa0_ = int(PG.PDALL)
    p_ = one(ev(PK, {"a": "po:dep", "@A": "9"}), "FURN2 POCKET Deposit again")
    K.check(POCK[n0_:] == [("dep", "Skyy_Ench_Iron", "")] and PTOK[-1] == "k1" and int(PG.PDALL) == pa0_ + 1 and pr_(p_) == "Put in 1 kind (6 items)"
            and int(pg.pdAt) == 0, "FURN2 POCKET the second click = ONE dep per carried item of THIS pocket (storage + hotbar counted, all of it, the token) (%s %s)" % (POCK[n0_:], pr_(p_)))
    n0_ = len(POCK)
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit after the run")
    K.check(len(POCK) == n0_ and "click again" in pr_(p_), "FURN2 POCKET a third click = the offer again (the run used it up) (%s)" % pr_(p_))
    pg.pdAt = int(pg.pdAt) - 11000
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit 11 s later")
    K.check(len(POCK) == n0_ and "click again" in pr_(p_), "FURN2 POCKET a click over 10 s after the offer = the offer again, NO call (%s)" % pr_(p_))
    PDF["full"] = "Skyy_Ench_Iron"
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit into a full category")
    K.check(POCK[n0_:] == [("dep", "Skyy_Ench_Iron", "")] and pr_(p_) == "This category is full - level it up or upgrade its rarity",
            "FURN2 POCKET a full category = the Void's own reason, the run stops (%s)" % pr_(p_))
    PDF["full"] = None
    put(PK, "storage", fr_[0], ISc("Ore_Copper", 3).withMetadata(IDMc.KEYED_CODEC, IDMc(MSGc.raw("Odd Ore"), MSGc.raw("odd"))))
    n0_ = len(POCK)
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit, the picked item only with extra data")
    K.check(len(POCK) == n0_ and pr_(p_) == PDT["PD_META"] and int(pg.pdAt) == 0, "FURN2 POCKET the picked item only as an extra-data stack = says so, NO call, no offer armed (%s)" % pr_(p_))
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit again after the extra-data line")
    K.check(len(POCK) == n0_, "FURN2 POCKET ... and a second click still moves nothing")
    inv(PK, "storage").removeItemStackFromSlot(JShort(fr_[0]))
    sp_ = pg.psel
    pg.psel = None
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit with nothing picked")
    K.check(len(POCK) == n0_ and pr_(p_) == PDT["PD_OFFERP"].replace("{N}", "1").replace("{C}", "Mining"), "FURN2 POCKET nothing picked + Mining items carried = the offer (%s)" % pr_(p_))
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit again with nothing picked")
    K.check(POCK[n0_:] == [("dep", "Skyy_Ench_Iron", "")], "FURN2 POCKET ... the second click deposits them (%s)" % POCK[n0_:])
    for f_, s_ in (("storage", fr_[1]), ("hotbar", hf_), ("storage", fr_[2])):
        if at(PK, f_, s_) is not None:
            inv(PK, f_).removeItemStackFromSlot(JShort(s_))
    p_ = one(ev(PK, {"a": "po:dep", "@A": ""}), "FURN2 POCKET Deposit, nothing picked, nothing carried")
    K.check(len(POCK) == n0_ + 1 and pr_(p_) == PDT["PD_NONEP"].replace("{C}", "Mining"), "FURN2 POCKET nothing picked + nothing carried = the reason, NO call (%s)" % pr_(p_))
    pg.psel = sp_
    BR.put("sacks:fn:pocket", Fn(f_pact))
    BR.remove("sacks:fn:catOf")
    pg.pdAt = 0
    PKT["t"] = "k2"
    p_ = one(ev(PK, {"a": "ppn"}), "INV4 FIX a redraw after a profile switch")
    K.check(pg.psel is None and str(pg.pkey) == "k2" and "Your profile changed" in (sval(cmap(p_), "#SkyyInvPr.Text") or ""),
            "INV4 FIX a profile switch seen on a redraw clears the pick and says so (%s)" % sval(cmap(p_), "#SkyyInvPr.Text"))
    n0_ = len(POCK)
    one(ev(PK, {"a": "po:sell", "@A": ""}), "INV4 FIX Sell after the switch")
    K.eq(len(POCK), n0_, "INV4 FIX Sell after a profile switch with the old pick: no call (nothing sold)")
    one(ev(PK, {"a": "pgs", "SlotIndex": 0}), "INV4 FIX pick again")
    one(ev(PK, {"a": "po:wd", "@A": "1"}), "INV4 FIX Withdraw on the new profile")
    K.check(PTOK[-1] == "k2" and POCK[-1] == ("wd", "Ore_Copper", "1"), "INV4 FIX the action carries the new profile's token")
    p_ = one(ev(PK, {"a": "pf"}), "INV4 Enchanted only")
    K.check("Skyy_Ench_Iron" in cmap(p_).get("#SkyyInvPg.Slots", "") and "Ore_Copper" not in cmap(p_).get("#SkyyInvPg.Slots", "") and sval(cmap(p_), "#SkyyInvPf.Text") == "Enchanted only - On",
            "INV4 Enchanted only shows only Enchanted items")
    one(ev(PK, {"a": "pf"}), "INV4 Enchanted only off")
    p_ = one(ev(PK, {"a": "pq", "@S": "rock"}), "INV4 pocket search")
    K.check("Rock_Stone" in cmap(p_).get("#SkyyInvPg.Slots", "") and "Ore_Copper" not in cmap(p_).get("#SkyyInvPg.Slots", ""), "INV4 the pocket search filters the grid")
    p_ = one(ev(PK, {"a": "pt:0"}), "INV4 back to Craft")
    K.check(str(pg.mode) == "c" and "#SkyyInvCg.Slots" in cmap(p_), "INV4 the Craft tab = the craft panel again")
    p_ = one(ev(PK, {"a": "sum"}), "INV4 Summon")
    K.check(RIDE == [str(PK.pr.getUuid())] and cap_of(p_) == "Mounting your Horse", "INV4 SUMMON = pets:fn:ride with your UUID, its answer as the caption (%s)" % cap_of(p_))
    bk_ = [str(x_) for x_ in pg.cbenches]
    if "Tannery" in bk_:
        p_ = one(ev(PK, {"a": "cb:%d" % bk_.index("Tannery")}), "INV4 Tanning tab")
        K.check(TAN == [str(PK.pr.getUuid())] and cap_of(p_) == "Opening the Tannery", "INV4 the Tanning tab = sacks:fn:openTannery (%s)" % cap_of(p_))
    else:
        K.check(False, "INV4 the Tanning tab is drawn in the Void mode (benches %s)" % bk_)
    for k_ in NEW:
        BR.remove(k_)
    pg.shut()
    E.pump(PK)
    # ---- INV5 (0.3.54; "Start it now" 11-20, popup "Inside the inventory (Recommended)"): the Charms panel (SkyyAccessories 0.5.37 acc:fn:charms)
    FC1, SPD_, LAN_ = "Skyy_Charm_Furnace_T1", "Skyy_Talisman_Speed_Common", "Skyy_Talisman_Lantern_Common"
    for iid_ in (FC1, SPD_, LAN_):
        it_ = Ucls.allocateInstance(ITc.class_)
        E.jf(ITc.class_, "id").set(it_, iid_)
        E.jf(ITc.class_, "translationProperties").set(it_, Ucls.allocateInstance(ITPc.class_))
        E.jf(ITc.class_, "maxStack").setInt(it_, 1)
