    print("   (INV6 FIX raw engine swap probe: %s; stone, apples %s -> %s)" % (e_, n0_, (cntB("Rock_Stone"), cntB("Plant_Fruit_Apple"))))
    E.jf(ITc.class_, "utility").set(amap.get("Rock_Stone"), IUc.DEFAULT)
    E.jf(ITc.class_, "utility").set(amap.get("Plant_Fruit_Apple"), IUc.DEFAULT)
    # ---- DROP1 (0.3.65): armour (PA) + off-hand (PB, a usable off-hand item) onto the DROP slot - each piece put back after (later checks)
    ST.DROPPER = Dropper(True)
    ah_ = at(PA, "armor", 0)
    del DROPS[:]
    pgA.lastMoveAt = 0
    p_ = one(ev(PA, {"a": "dz", "SlotIndex": 0, "SourceInventorySectionId": -3, "SourceSlotId": 0, "ItemStackId": ah_[0] if ah_ else "", "ItemStackQuantity": 1}), "DROP1 DRAG an armour piece")
    K.check(ah_ is not None and DROPS == [(ah_[0], 1)] and at(PA, "armor", 0) is None and cap_of(p_) == "Dropped",
            "DROP1 DRAG an armour piece onto DROP = dropped, the armour slot empty (%s %s %s)" % (ah_, DROPS, cap_of(p_)))
    if ah_ is not None and at(PA, "armor", 0) is None:
        put(PA, "armor", 0, ISc(ah_[0], ah_[1]))
    pgA.lastMoveAt = 0
    E.jf(ITc.class_, "utility").set(amap.get("Plant_Fruit_Apple"), UU_)
    uh_ = at(PB, "utility", 0)
    if uh_ is None:
        put(PB, "utility", 0, ISc("Plant_Fruit_Apple", 3))
        uh_ = at(PB, "utility", 0)
    del DROPS[:]
    pgB.lastMoveAt = 0
    p_ = one(ev(PB, {"a": "dz", "SlotIndex": 0, "SourceInventorySectionId": -5, "SourceSlotId": 0, "ItemStackId": uh_[0] if uh_ else "", "ItemStackQuantity": uh_[1] if uh_ else 1}), "DROP1 DRAG an off-hand item")
    K.check(uh_ is not None and DROPS == [uh_] and at(PB, "utility", 0) is None and cap_of(p_) == "Dropped",
            "DROP1 DRAG an off-hand item onto DROP = dropped, the off-hand slot empty (%s %s %s)" % (uh_, DROPS, cap_of(p_)))
    if uh_ is not None and at(PB, "utility", 0) is None:
        put(PB, "utility", 0, ISc(uh_[0], uh_[1]))
    E.jf(ITc.class_, "utility").set(amap.get("Plant_Fruit_Apple"), IUc.DEFAULT)
    ST.DROPPER = None
    pgB.lastMoveAt = 0
    E.pump(PA)
    E.pump(PB)
    pgB.shut()
    E.pump(PB)
    ST.LASTNATIVE.put(PA.pr.getUuid(), JClass("java.lang.Long")(JClass("java.lang.System").currentTimeMillis()))
    p_ = one(drag(PA, "s", 2, "a", 0, iid="Armor_Iron_Head")[1], "INV6 drag right after a native move")
    K.check(at(PA, "armor", 0) == ("Armor_Gold_Head", 1) and cap_of(p_) == "Moved by the game", "INV6 ARMOUR a drop right after a native Move = left to the game (no double move)")
    ST.LASTNATIVE.remove(PA.pr.getUuid())
    one(ev(PA, {"a": "sc", "g": "a", "SlotIndex": 0, "ShiftHeld": True}), "INV6 shift pick on armour")
    p_ = one(ev(PA, {"a": "rl", "g": "a", "SlotIndex": 0, "ShiftHeld": True}), "INV6 shift release on armour")
    K.check(at(PA, "armor", 0) == ("Armor_Gold_Head", 1) and cap_of(p_) == "Quick moved", "INV6 ARMOUR shift-click = the game's own SmartMove (no server move here)")
    K.eq(tot6(), T6, "INV6 ARMOUR every item total unchanged (no dupe, no loss)")
    pgA.shut()
    E.pump(PA)
    # ---- TP: the stand-in TeleportPlugin (the 0.3.37 harness's way) with 8 warps
    import time as _t6
    TPPc, WARPc = JClass("com.hypixel.hytale.builtin.teleport.TeleportPlugin"), JClass("com.hypixel.hytale.builtin.teleport.Warp")
    ModC_ = JClass("java.lang.reflect.Modifier")
    tpi_ = Ucls.allocateInstance(TPPc.class_)
    fl_ = list(TPPc.class_.getDeclaredFields())
    WARPS = JClass("java.util.concurrent.ConcurrentHashMap")()
    for f_ in fl_:
        f_.setAccessible(True)
        if ModC_.isStatic(f_.getModifiers()) and f_.getType() == TPPc.class_:
            f_.set(None, tpi_)
        elif not ModC_.isStatic(f_.getModifiers()) and JClass("java.util.Map").class_.isAssignableFrom(f_.getType()):
            f_.set(tpi_, WARPS)
        elif not ModC_.isStatic(f_.getModifiers()) and str(f_.getType().getName()) == "boolean":
            f_.setBoolean(tpi_, True)
        elif not ModC_.isStatic(f_.getModifiers()) and str(f_.getType().getName()) == "java.util.concurrent.atomic.AtomicBoolean":
            f_.set(tpi_, JClass("java.util.concurrent.atomic.AtomicBoolean")(True))

    def mkwarp(name):
        w_ = WARPc()
        for f_ in WARPc.class_.getDeclaredFields():
            f_.setAccessible(True)
            n_ = str(f_.getName())
            if n_ == "id":
                f_.set(w_, name)
            elif n_ == "world":
                f_.set(w_, "nowhere_world")
            elif n_ == "creator":
                f_.set(w_, "Skyy")
        WARPS.put(name, w_)
    for n_ in ("mines", "dock", "w1", "w2", "w3", "w4", "w5", "w6"):
        mkwarp(n_)
    K.check(TPPc.get() is not None and TPPc.get().isWarpsLoaded() and WARPS.size() == 8, "INV6 TP setup: 8 warps loaded")
    tpdir = os.path.join(home, "invtp")
    ST.TPDIR = Paths.get(tpdir)
    PT = E.player(uid=UUIDc(0x57, 0x57), name="SkyyTpA")
    byU.put(PT.pr.getUuid(), PT.pr)
    u6 = str(PT.pr.getUuid())
    f1 = os.path.join(tpdir, u6 + ".properties")

    def rowfile(path_, wait=True):
        for _w in range(40 if wait else 1):
            if os.path.exists(path_):
                try:
                    tx_ = open(path_, encoding="utf8").read()
                    return dict(l_.split("=", 1) for l_ in tx_.splitlines() if l_.startswith("slot."))
                except OSError:
                    pass   # the IO thread's atomic move at this moment (Windows sharing) - read again
            _t6.sleep(0.05)
        return None

    def waitrow(path_, want):
        got_ = None
        for _w in range(60):
            got_ = rowfile(path_, wait=False)
            if got_ == want:
                return got_
            _t6.sleep(0.05)
        return got_

    def rowslots(p_):
        try:
            sl_ = json.loads(cmap(p_).get("#SkyyInvTp.Slots", "{}")).get("0", [])
        except Exception:
            return None
        return [None if not s_ or not s_.get("Name") or str(s_.get("Name")).startswith("Empty") else str(s_.get("Name")).split("  - ")[0] for s_ in sl_]
    pgT = ST.openPage(PT.ref, PT.st, PT.pr, "test")
    E.pump(PT)
    p_ = one(ev(PT, {"a": "cb:0"}), "INV6 TP the first draw")
    rs_ = rowslots(p_)
    K.check(rs_ is not None and rs_[:2] == ["Island", "Hub"] and rs_[2:] == [None] * 6 and not os.path.exists(f1) and sval(cmap(p_), "#SkyyInvTpE.Text") == "Edit",
            "INV6 TP the default row Island + Hub, no file written, the button says Edit (%s)" % rs_)
    p_ = one(ev(PT, {"a": "tpe"}), "INV6 TP Edit")
    cm = cmap(p_) if p_ else {}
    gs_ = cm.get("#SkyyInvTxG.Slots", "")
    K.check(str(pgT.mode) == "t" and "#SkyyInvCg.Slots" not in cm and "#SkyyInvIs.Slots" in cm and sval(cm, "#SkyyInvTpE.Text") == "Done"
            and "click to remove" in cm.get("#SkyyInvTp.Slots", ""), "INV6 TP Edit = the Teleports panel INSTEAD of the craft panel, the row says 'click to remove', the button Done")
    K.eq([str(x_) if x_ is not None else None for x_ in list(pgT.tcand)[:9]], ["warp:dock", "warp:mines", "warp:w1", "warp:w2", "warp:w3", "warp:w4", "warp:w5", "warp:w6", None],
         "INV6 TP the candidates: the warps you can use A-Z, not Island / Hub (in the row), no Spawn")
    K.check('"dock"' in gs_ and '"w6"' in gs_ and nometa(p_) and sval(cm, "#SkyyInvTxPn.Text") == "1 / 1", "INV6 TP the candidate grid: the warps by name (icons only for ids the server knows), no metadata, 1 page")
    p_ = one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 TP add dock")
    K.check(waitrow(f1, {"slot.0": "tp:island", "slot.1": "tp:hub", "slot.2": "warp:dock"}) == {"slot.0": "tp:island", "slot.1": "tp:hub", "slot.2": "warp:dock"}
            and "Added dock to row slot 3" in (sval(cmap(p_), "#SkyyInvTxM.Text") or "") and rowslots(p_)[2] is not None,
            "INV6 TP add a warp = the first empty slot, SAVED AT ONCE to invtp/<uuid>.properties (read back) (%s)" % sval(cmap(p_), "#SkyyInvTxM.Text"))
    one(ev(PT, {"a": "tp", "SlotIndex": 6}), "INV6 TP pick row slot 7")
    K.eq(int(pgT.tslot), 6, "INV6 TP a click on an empty row slot while editing = picked")
    p_ = one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 TP add mines into the picked slot")
    K.eq(waitrow(f1, {"slot.0": "tp:island", "slot.1": "tp:hub", "slot.2": "warp:dock", "slot.6": "warp:mines"}),
         {"slot.0": "tp:island", "slot.1": "tp:hub", "slot.2": "warp:dock", "slot.6": "warp:mines"}, "INV6 TP add into the PICKED empty slot (7)")
    p_ = one(ev(PT, {"a": "tp", "SlotIndex": 0}), "INV6 TP remove Island")
    K.check(waitrow(f1, {"slot.1": "tp:hub", "slot.2": "warp:dock", "slot.6": "warp:mines"}) == {"slot.1": "tp:hub", "slot.2": "warp:dock", "slot.6": "warp:mines"}
            and "Removed Island" in (sval(cmap(p_), "#SkyyInvTxM.Text") or ""), "INV6 TP a click on a row teleport while editing = removed (saved)")
    p_ = one(ev(PT, {"a": "tp", "SlotIndex": 0}), "INV6 TP the same click again")
    K.check(int(pgT.tslot) == 0 and rowfile(f1) == {"slot.1": "tp:hub", "slot.2": "warp:dock", "slot.6": "warp:mines"},
            "INV6 TP a double click on a removed teleport = the now empty slot is picked, nothing else changes")
    pgT.tslot = -1
    for k_ in range(5):
        pgT.lastMoveAt = 0
        one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 TP fill %d" % k_)
    pgT.lastMoveAt = 0
    p_ = one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 TP a full row")
    full_ = None
    for _w in range(60):
        full_ = rowfile(f1, wait=False)
        if full_ is not None and len(full_) == 8:
            break
        _t6.sleep(0.05)
    _t6.sleep(0.2)   # the IO thread is done before the bytes are kept
    K.check(full_ is not None and len(full_) == 8 and "Your row is full" in (sval(cmap(p_), "#SkyyInvTxM.Text") or ""), "INV6 TP a full row: the 9th refused (%s)" % sval(cmap(p_), "#SkyyInvTxM.Text"))
    fb1 = open(f1, "rb").read()
    # ---- per PROFILE
    BR.put("profile:fn:key", Fn(lambda o: str(o) + "-p2"))
    p_ = one(ev(PT, {"a": "txn"}), "INV6 TP a redraw on profile 2")
    rs_ = rowslots(p_)
    K.check(rs_ is not None and rs_[:2] == ["Island", "Hub"] and rs_[2:] == [None] * 6 and str(pgT.tkey) == u6 + "-p2" and open(f1, "rb").read() == fb1
            and not os.path.exists(os.path.join(tpdir, u6 + "-p2.properties")), "INV6 TP profile 2 has its OWN row (the default), profile 1's file untouched (%s)" % rs_)
    BR.remove("profile:fn:key")
    one(ev(PT, {"a": "txn"}), "INV6 TP back on profile 1")
    BR.put("profile:fn:key", Fn(lambda o: str(o) + "-p2"))
    pgT.lastMoveAt = 0
    p_ = one(ev(PT, {"a": "tp", "SlotIndex": 2}), "INV6 TP a remove after a profile switch (not redrawn)")
    K.check(open(f1, "rb").read() == fb1 and not os.path.exists(os.path.join(tpdir, u6 + "-p2.properties"))
            and "Your profile changed" in (sval(cmap(p_), "#SkyyInvTxM.Text") or ""), "INV6 TP a profile switch between draw and click = refused, nothing written")
    BR.put("profile:fn:key", Fn(lambda o: str(o) + "-p3"))
    f3 = os.path.join(tpdir, u6 + "-p3.properties")
    open(f3, "wb").write(b"_v=1\nslot.0=\\uZZZZ\n")
    fb3 = open(f3, "rb").read()
    p_ = one(ev(PT, {"a": "txn"}), "INV6 TP an unreadable row file")
    rs_ = rowslots(p_)
    K.check(rs_ is not None and rs_[:2] == ["Island", "Hub"] and "could not be read" in (sval(cmap(p_), "#SkyyInvTpNote.Text") or ""), "INV6 TP an unreadable file: the default shown + said so (%s / %s)" % (rs_, sval(cmap(p_), "#SkyyInvTpNote.Text")))
    pgT.lastMoveAt = 0
    p_ = one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 TP an add on the unreadable profile")
    _t6.sleep(0.3)
    K.check(open(f3, "rb").read() == fb3 and "could not be read" in (sval(cmap(p_), "#SkyyInvTxM.Text") or ""), "INV6 TP ... an edit refused, the file NEVER overwritten (%s)" % sval(cmap(p_), "#SkyyInvTxM.Text"))
    # FIX (critic 1 #1): a FAILED row write is said on the panel and written again later (never a silent success)
    BR.put("profile:fn:key", Fn(lambda o: str(o) + "-p4"))
    k4 = u6 + "-p4"
    blk_ = os.path.join(home, "tpblock")
    open(blk_, "wb").write(b"x")   # a FILE where the folder should be: every write fails
    ST.TPDIR = Paths.get(os.path.join(blk_, "invtp"))
    one(ev(PT, {"a": "txn"}), "INV6 FIX1 draw on profile 4")
    pgT.lastMoveAt = 0
    pgT.tslot = -1
    one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 FIX1 an add whose write fails")
    for _w in range(60):
        if ST.TPDIRTY.containsKey(k4):
            break
        _t6.sleep(0.05)
    p_ = one(ev(PT, {"a": "txn"}), "INV6 FIX1 redraw after the failed write")
    K.check(bool(ST.TPDIRTY.containsKey(k4)) and "not saved yet" in (sval(cmap(p_), "#SkyyInvTpNote.Text") or ""),
            "INV6 FIX1 a failed write: marked unsaved + the panel SAYS it (%s)" % sval(cmap(p_), "#SkyyInvTpNote.Text"))
    pgT.lastMoveAt = 0
    p_ = one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 FIX1 a second add while unsaved")
    K.check("NOT SAVED" in (sval(cmap(p_), "#SkyyInvTxM.Text") or ""), "INV6 FIX1 an edit while unsaved says NOT SAVED (%s)" % sval(cmap(p_), "#SkyyInvTxM.Text"))
    ST.TPDIR = Paths.get(tpdir)
    ST.TPDIRTY.put(k4, JClass("java.lang.Long")(0))   # the 30 s retry gap has passed
    one(ev(PT, {"a": "txn"}), "INV6 FIX1 a redraw after the folder is writable again")
    f4 = os.path.join(tpdir, k4 + ".properties")
    want4 = {"slot.0": "tp:island", "slot.1": "tp:hub", "slot.2": "warp:dock", "slot.3": "warp:mines"}
    K.check(waitrow(f4, want4) == want4 and not ST.TPDIRTY.containsKey(k4), "INV6 FIX1 the retry WRITES the kept row (both edits) and clears the mark (%s)" % rowfile(f4, wait=False))
    # FIX (critic 1 #2 / critic 3 #2): a slot value this version does not know is KEPT in the file; bad text is dropped (warned)
    BR.put("profile:fn:key", Fn(lambda o: str(o) + "-p5"))
    f5 = os.path.join(tpdir, u6 + "-p5.properties")
    open(f5, "wb").write(b"_v=2\nslot.0=tp:island\nslot.1=home:base\nslot.2=warp:dock\nslot.4=a b c\n")
    p_ = one(ev(PT, {"a": "txn"}), "INV6 FIX2 draw a row with a newer key")
    rs_ = rowslots(p_)
    K.check(rs_ is not None and rs_[0] == "Island" and rs_[1] is None and rs_[2] is not None and rs_[4] is None, "INV6 FIX2 the unknown key shows as an empty slot (%s)" % rs_)
    pgT.lastMoveAt = 0
    pgT.tslot = -1
    one(ev(PT, {"a": "txg", "SlotIndex": 0}), "INV6 FIX2 an add on that row")
    want5 = {"slot.0": "tp:island", "slot.1": "home:base", "slot.2": "warp:dock", "slot.3": "tp:hub"}
    K.eq(waitrow(f5, want5), want5, "INV6 FIX2 the save KEEPS slot.1=home:base verbatim, the add (Hub, the first candidate) skips that slot, the bad text is dropped")
    BR.remove("profile:fn:key")
    p_ = one(ev(PT, {"a": "txd"}), "INV6 TP Done")
    K.check(str(pgT.mode) == "c" and "#SkyyInvCg.Slots" in cmap(p_) and sval(cmap(p_), "#SkyyInvTpE.Text") == "Edit", "INV6 TP Done = the craft panel again, the button Edit")
    p_ = one(ev(PT, {"a": "tp", "SlotIndex": 2}), "INV6 TP click a warp whose world is not loaded")
    K.check(not bool(pgT.closed) and "is not loaded" in cap_of(p_), "INV6 TP a warp in the row whose world is not loaded = a caption, the page stays (%s)" % cap_of(p_))
    WARPS.remove("dock")
    p_ = one(ev(PT, {"a": "cb:0"}), "INV6 TP redraw with dock removed")
    K.check("dock (gone)" in cmap(p_).get("#SkyyInvTp.Slots", ""), "INV6 TP a removed warp is drawn '(gone)', greyed")
    p_ = one(ev(PT, {"a": "tp", "SlotIndex": 2}), "INV6 TP click the removed warp")
    K.check(not bool(pgT.closed) and "was removed" in cap_of(p_), "INV6 TP a click on a removed warp = a caption (%s)" % cap_of(p_))
    pgT.shut()
    E.pump(PT)
    # ---- POCKET: Upgrades + Auto-compact
    CMP = {"st": "=1", "calls": [], "open": []}

    def f_pl6(o):
        return "ok|Mining|3|Rare|240|6720|1|tok6\nOre_Copper|128|0|5"

    def f_pk6(o):
        CMP["calls"].append((str(o[1]), str(o[2]), str(o[4]) if len(o) > 4 else None))
        return CMP["st"] if str(o[1]) == "cmpst" else "=Auto-compact paused for Mining - nothing compacts there until you turn it on"
    BR.put("sacks:fn:pocketList", Fn(f_pl6))
    BR.put("sacks:fn:pocket", Fn(f_pk6))
    pgP = ST.openPage(PT.ref, PT.st, PT.pr, "test")
    E.pump(PT)
    p_ = one(ev(PT, {"a": "pt:1"}), "INV6 POCKET without openPocket")
    K.check(sval(cmap(p_), "#SkyyInvPCm.Text") == "Auto-compact" and not [c_ for c_ in CMP["calls"] if c_[0] == "cmpst"], "INV6 POCKET without SkyySacks 0.8.39: the button says Auto-compact, no state call")
    p_ = one(ev(PT, {"a": "pcm"}), "INV6 POCKET Auto-compact without 0.8.39")
    K.check(not CMP["calls"] and "Void page" in (sval(cmap(p_), "#SkyyInvPr.Text") or ""), "INV6 POCKET ... a click = a hint, no call")
    BR.put("sacks:fn:openPocket", Fn(lambda o: (CMP["open"].append((str(o[0]), str(o[1]))), TRUE)[1]))
    p_ = one(ev(PT, {"a": "ppn"}), "INV6 POCKET with 0.8.39")
    K.check(sval(cmap(p_), "#SkyyInvPCm.Text") == "Compact: On" and CMP["calls"][-1] == ("cmpst", "Mining", "tok6"), "INV6 POCKET the button reads the state (On) with the list's token")
    for st_, want_ in (("=0", "Compact: Off"), ("=b", "Compact: Buy"), ("=-", "Compact: None"), ("=x", "Compact: None")):
        CMP["st"] = st_
        K.eq(sval(cmap(one(ev(PT, {"a": "ppn"}), "INV6 POCKET state " + st_)), "#SkyyInvPCm.Text"), want_, "INV6 POCKET state %s -> %s" % (st_, want_))
    CMP["st"] = "=b"
    n0_ = len([c_ for c_ in CMP["calls"] if c_[0] == "cmp"])
    p_ = one(ev(PT, {"a": "pcm"}), "INV6 POCKET Auto-compact not bought")
    K.check(len([c_ for c_ in CMP["calls"] if c_[0] == "cmp"]) == n0_ and "Buy Auto-compact" in (sval(cmap(p_), "#SkyyInvPr.Text") or ""), "INV6 POCKET not bought: a hint, NO toggle call (buying stays on the Void page)")
    CMP["st"] = "=1"
    pgP.lastMoveAt = 0
    p_ = one(ev(PT, {"a": "pcm"}), "INV6 POCKET Auto-compact Pause")
    K.check([c_ for c_ in CMP["calls"] if c_[0] == "cmp"] == [("cmp", "Mining", "tok6")] and "paused for Mining" in (sval(cmap(p_), "#SkyyInvPr.Text") or ""),
            "INV6 POCKET a click = ONE cmp call with the pocket + the list's token, the answer shown")
    p_ = one(ev(PT, {"a": "pcm"}), "INV6 POCKET the same click again")
    K.eq(len([c_ for c_ in CMP["calls"] if c_[0] == "cmp"]), 1, "INV6 POCKET a double click within 1.5 s = one toggle")
    # FIX (critic 2 #2): the list answered WITHOUT a profile token -> the toggle is refused (never toggles whichever profile is settled now)
    BR.put("sacks:fn:pocketList", Fn(lambda o: "ok|Mining|3|Rare|240|6720|1|\nOre_Copper|128|0|5"))
    one(ev(PT, {"a": "ppn"}), "INV6 FIX POCKET redraw without a token")
    pgP.lastMoveAt = 0
    p_ = one(ev(PT, {"a": "pcm"}), "INV6 FIX POCKET Auto-compact without a token")
    K.check(len([c_ for c_ in CMP["calls"] if c_[0] == "cmp"]) == 1 and "not settled" in (sval(cmap(p_), "#SkyyInvPr.Text") or ""),
            "INV6 FIX POCKET no profile token = NO cmp call, a hint (%s)" % sval(cmap(p_), "#SkyyInvPr.Text"))
    BR.put("sacks:fn:pocketList", Fn(f_pl6))
    one(ev(PT, {"a": "ppn"}), "INV6 FIX POCKET redraw with the token again")
    p_ = one(ev(PT, {"a": "pup"}), "INV6 POCKET Upgrades")
    K.check(CMP["open"] == [(u6, "Mining")], "INV6 POCKET Upgrades = ONE sacks:fn:openPocket with the pocket (%s)" % CMP["open"])
    for k_ in ("sacks:fn:pocketList", "sacks:fn:pocket", "sacks:fn:openPocket"):
        BR.remove(k_)
    pgP.shut()
    E.pump(PT)
    # ---- INV7 (0.3.56; "Start it now" 11-21): the Furnace / Tanning panel, skill icons + XP bars, the class XP bar, Right now rows
    FX = {"calls": [], "lists": [], "tok": "ftok1", "off": None, "ans": {}, "fs": "2"}
    FREC = [("Skyy_R_Cu", "Ingredient_Bar_Iron", 1, 1792, "T1 Copper", "Copper Ingot", "", "2s"),
            ("Skyy_R_Fe", "Ingredient_Bar_Iron", 1, 1262, "T2 Iron", "Iron Ingot", "", "2s"),
            ("Skyy_R_Br", "Skyy_No_Such_Bar", 1, 0, "T3 Bronze", "Bronze Ingot", "Furnace Charm T2 unlocks this", "3s"),
            ("Skyy_R_Th", "Ingredient_Bar_Iron", 1, 86, "T4 Thorium", "Thorium Ingot", "", "4s"),
            ("Skyy_R_Ch", "Wood_Oak_Trunk", 1, 640, "", "Charcoal", "", "1s"),
            ("Skyy_R_Gl", "Rock_Stone", 1, 0, "", "Glass", "", "1s"),
            ("Skyy_R_Ba", "Rock_Stone", 2, 12, "", "Basalt", "", "1s")]

    def f_flist(o):
        a_ = [str(x_) if x_ is not None else None for x_ in list(o)]
        FX["lists"].append(tuple(a_[1:]))
        if a_[1] == "sum":
            return "sum|Furnace|64|128|Iron Ingot\nsum|Tannery|0|12|"
        if FX["off"]:
            return "off|" + FX["off"]
        b_ = a_[1]
        fu_ = "1" if b_ == "Furnace" else "0"
        ls_ = ["ok|%s|3|%s III - Furnace Charm T3|Smelting Iron Ingot - 12s left|40|312|1000|%s|640|1000|%s|16m 10s|20m|64|%s" % (b_, b_, fu_, FX["fs"], FX["tok"]),
               "q|Ingredient_Bar_Iron|Iron Ingot|64|44s|44s", "q|Ingredient_Bar_Iron|Copper Ingot|128|4m|4m 44s", "o|Ingredient_Bar_Iron|Iron Ingot|64",
               "f|Wood_Oak_Trunk|Oak Log|640|16m 10s"]
        if fu_ == "1":
            ls_ += ["h|Wood_Oak_Trunk|Oak Log|1000", "h|Rock_Stone|Stone Fuel|5"]
        q_ = (a_[3] or "").lower()
        for r_ in FREC:
            if q_ and q_ not in r_[5].lower():
                continue
            ls_.append("r|%s|%s|%d|%d|%s|%s|%s|%s" % r_)
        if a_[2]:
            ls_.append("i|Ore_Iron|Iron Ore|1262|1")
        return "\n".join(ls_)

    def f_fact(o):
        a_ = tuple(str(x_) if x_ is not None else None for x_ in list(o))
        FX["calls"].append(a_[1:])
        return FX["ans"].get(a_[2], "+queued 1 x Iron Ingot in the Furnace")
    nf_ = lambda: len(FX["calls"])
    pgF = ST.openPage(PK.ref, PK.st, PK.pr, "test")
    E.pump(PK)
    one(ev(PK, {"a": "cb:0"}), "INV7 the craft panel first")
    bks_ = [str(x_) for x_ in list(pgF.cbenches)]
    fi_, ti_ = bks_.index("Furnace"), bks_.index("Tannery")
    o0_ = len(OPENED)
    p_ = one(ev(PK, {"a": "cb:%d" % fi_}), "INV7 FURN the Furnace tab without SkyySacks 0.8.40")
    K.check(len(OPENED) == o0_ + 1 and str(pgF.mode) == "c", "INV7 FURN without sacks:fn:furnList the Furnace tab opens the pack's own page (0.3.55)")
    BR.put("sacks:fn:furnList", Fn(f_flist))
    BR.put("sacks:fn:furn", Fn(f_fact))
    p_ = one(ev(PK, {"a": "cb:%d" % fi_}), "INV7 FURN the Furnace tab")
    cm = cmap(p_) if p_ else {}
    bl = binds_of(p_) if p_ else []
    K.check(str(pgF.mode) == "f" and "#SkyyInvCg.Slots" not in cm and "#SkyyInvFxG.Slots" in cm and FX["lists"][-1] == ("Furnace", "", ""),
            "INV7 FURN the Furnace tab = the panel INSTEAD of the craft panel, ONE furnList call (bench, no pick, no search)")
    K.check(sval(cm, "#SkyyInvBt%d.Text" % fi_) == "Furnace" and TSEL_ in mk_of(p_, "SkyyInvBt%d" % fi_) and sval(cm, "#SkyyInvBt0.Text") == "Crafting",
            "INV7 FURN the bench tabs on the panel, Furnace selected")
    K.eq(sval(cm, "#SkyyInvFxS.Text"), "Furnace III - Furnace Charm T3", "INV7 FURN the status line")
    K.eq([sval(cm, "#SkyyInvFr%d.Text" % k_) for k_ in range(5)], ["Copper Ingot  T1  1,792", "Iron Ingot  T2  1,262", "Bronze Ingot  T3  locked",
                                                                   "Thorium Ingot  T4  86", "Charcoal  640"], "INV7 FURN the list rows (SkyySacks' order: ingots first)")
    gs_ = cm.get("#SkyyInvFxG.Slots", "")
    K.check("Ingredient_Bar_Iron" in gs_ and "Skyy_No_Such_Bar" not in gs_ and "Bronze Ingot" in gs_ and nometa(p_),
            "INV7 FURN the list grid: icons for ids the server knows, an unknown output = name only, no metadata")
    K.check(sval(cm, "#SkyyInvFpN.Text") == "1 / 2" and sval(cm, "#SkyyInvFxLi.Text") == "7 recipes - ingots first, by tier", "INV7 FURN 7 recipes = 2 pages, the info line")
    K.check(sval(cm, "#SkyyInvFxQt.Text") == "QUEUE  312 / 1,000" and sval(cm, "#SkyyInvFu0.Text") == "Iron Ingot x64  -  done in 44s"
            and sval(cm, "#SkyyInvFxRh.Text") == "READY  64" and sval(cm, "#SkyyInvFo0.Text") == "Iron Ingot x64" and sval(cm, "#SkyyInvFo1.Text") == "",
            "INV7 FURN the queue + ready lines")
    K.check(sval(cm, "#SkyyInvFxF0.Text") == "Oak Log x640" and sval(cm, "#SkyyInvFxFn.Text") == "needs 20m - has 16m 10s"
            and sval(cm, "#SkyyInvFxNt.Text") == "Not enough fuel for the whole queue" and "Wood_Oak_Trunk" in cm.get("#SkyyInvFxF.Slots", ""),
            "INV7 FURN the FUEL slot (the loaded fuel, its count), the need / has line, the fuel note")
    vis_ = lambda c_, k_: sval(c_, "#SkyyInv%s.Visible" % k_) in (True, "true")
    K.check(vis_(cm, "FxFnR") and not vis_(cm, "FxFn") and not vis_(cm, "FxFnG") and sval(cm, "#SkyyInvFxFnR.Text") == "needs 20m - has 16m 10s"
            and vis_(cm, "FxNtR") and not vis_(cm, "FxNt") and not vis_(cm, "FxNtG") and sval(cm, "#SkyyInvFxNtR.Text") == "Not enough fuel for the whole queue",
            "FIX1 short fuel = the RED fuel line + the RED note shown, the others hidden (ui.md 2026-10-18)")
    TXW_ = int(DATA.FX_TXW)
    px_ = lambda t_: int(pgF.fxPx(t_))
    r1_ = str(pgF.fxRow("> ", "Enchanted Copper Ingot Alloy", "T2", "locked"))
    r2_ = str(pgF.fxRow("", "Enchanted Super Compressed Thorium Alloy Ingot", "T4", "1,234"))
    r3_ = str(pgF.fxRow("", "Copper Ingot", "T1", "1,792"))
    K.check(px_(r1_) <= TXW_ and "T2" not in r1_ and r1_.startswith("> Enchanted") and r1_.endswith("locked")
            and px_(r2_) <= TXW_ and ".." in r2_ and r2_.endswith("1,234") and "T4" not in r2_ and r3_ == "Copper Ingot  T1  1,792",
            "FIX2 a long row drops its tier tag, a longer one is cut with '..', the count always shows, a short row stays whole (%r %r)" % (r1_, r2_))
    K.check(all(px_(sval(cm, "#SkyyInvFr%d.Text" % k_) or "") <= TXW_ for k_ in range(5)), "FIX2 every drawn list row fits the button")
    K.check(("SlotClicking", "#SkyyInvFxG") in [(b_[0], b_[1]) for b_ in bl] and ("Dropped", "#SkyyInvFxF") in [(b_[0], b_[1]) for b_ in bl]
            and ("Validating", "#SkyyInvFq") in [(b_[0], b_[1]) for b_ in bl] and "#SkyyInvFb2" in [b_[1] for b_ in bl] and "#SkyyInvFxCo" in [b_[1] for b_ in bl]
            and "#SkyyInvCg" not in [b_[1] for b_ in bl], "INV7 FURN the panel's bindings (list, fuel drop, search, buttons), none for the craft grid")
    p_ = one(ev(PK, {"a": "fpn"}), "INV7 FURN page 2")
    K.check(sval(cmap(p_), "#SkyyInvFr0.Text") == "Glass  0" and sval(cmap(p_), "#SkyyInvFr2.Text") == "" and sval(cmap(p_), "#SkyyInvFpN.Text") == "2 / 2", "INV7 FURN page 2")
    p_ = one(ev(PK, {"a": "fq", "@F": "iron"}), "INV7 FURN search")
    K.check(FX["lists"][-1] == ("Furnace", "", "iron") and int(pgF.fpage) == 0 and "search: iron" in (sval(cmap(p_), "#SkyyInvFxLi.Text") or ""),
            "INV7 FURN search: the typed words reach SkyySacks, page 1 (%s)" % sval(cmap(p_), "#SkyyInvFxLi.Text"))
    one(ev(PK, {"a": "fq", "@F": ""}), "INV7 FURN clear the search")
    # ---- FURN2 BENCH (0.3.66; Skyy 11-22 "i want a normal easy way to access this besides the right now tab."): the pinned tabs + paging
    def wid_(p_, i_):
        m_ = re.search(r"Width: (\d+)", mk_of(p_, "SkyyInvBt%s" % i_))
        return int(m_.group(1)) if m_ else -1
    bk0_ = [str(x_) for x_ in list(pgF.cbenches)]
    K.check(bk0_[-2:] == ["Furnace", "Tannery"] and bk0_[0] == "Crafting", "FURN2 BENCH Crafting first, Furnace + Tannery pinned last (%s)" % bk0_)
    AL = JClass("java.util.ArrayList")
    ten_ = AL()
    for n_ in ["Crafting", "Armor_Bench", "Furniture_Bench", "Arcane_Bench", "Salvagebench", "Farming_Bench", "Weapon_Bench", "Builders_Bench", "Furnace", "Tannery"]:
        ten_.add(n_)
    pgF.cbenches = ten_
    pgF.cboff = 0
    fbw_ = int(DATA.FX_BW)
    kF_ = (fbw_ - int(DATA.NAVW) - 4) // (int(DATA.TABMIN) + 4) - 3
    p_ = one(ev(PK, {"a": "fq", "@F": ""}), "FURN2 BENCH 10 benches on the Furnace panel")
    cm = cmap(p_) if p_ else {}
    shown_ = [k_ for k_ in range(10) if ("#SkyyInvBt%d.Text" % k_) in cm]
    K.check(shown_ == [0] + list(range(1, 1 + kF_)) + [8, 9] and sval(cm, "#SkyyInvBtM.Text") == "More" and ("Activating", "#SkyyInvBtM") in [b_[:2] for b_ in binds_of(p_)]
            and sval(cm, "#SkyyInvBt8.Text") == "Furnace" and sval(cm, "#SkyyInvBt9.Text") == "Tanning" and TSEL_ in mk_of(p_, "SkyyInvBt8")
            and min(wid_(p_, k_) for k_ in shown_) >= 60 and len(shown_) <= 8 and kF_ >= 1,
            "FURN2 BENCH the Furnace panel: Crafting + %d benches + More + Furnace (selected) + Tanning, every tab >= 60 px, at most 8 (%s %s)" % (kF_, shown_, [wid_(p_, k_) for k_ in shown_]))
    K.check(mk_of(p_, "SkyyInvBtM").find("Width: %d" % int(DATA.NAVW)) > 0 and sum(wid_(p_, k_) + 4 for k_ in shown_) + int(DATA.NAVW) + 4 <= fbw_ + 4,
            "FURN2 BENCH the Furnace row fits its width (no overlap at 1080p)")
    seen_ = set(shown_)
    m0_ = int(PG.MORES)
    for r_ in range(4):
        p_ = one(ev(PK, {"a": "cbm"}), "FURN2 BENCH More %d" % r_)
        cm = cmap(p_) if p_ else {}
        sh_ = [k_ for k_ in range(10) if ("#SkyyInvBt%d.Text" % k_) in cm]
        K.check(sh_[0] == 0 and sh_[-2:] == [8, 9] and str(pgF.mode) == "f", "FURN2 BENCH More keeps Crafting, Furnace, Tanning and the Furnace panel (%s)" % sh_)
        seen_ |= set(sh_)
    K.check(seen_ == set(range(10)) and int(PG.MORES) == m0_ + 4, "FURN2 BENCH More pages through every bench and wraps")
    pgF.cboff = 0
    p_ = one(ev(PK, {"a": "cb:9"}), "FURN2 BENCH the pinned Tanning tab")
    K.check(str(pgF.fbench) == "Tannery" and str(pgF.mode) == "f", "FURN2 BENCH the pinned Tanning tab (index 9) opens the Tanning panel")
    one(ev(PK, {"a": "cb:8"}), "FURN2 BENCH back to the Furnace")
    rs_ = AL()
    for n_ in bk0_:
        rs_.add(n_)
    pgF.cbenches = rs_
    # the craft panel with more benches from the recipe list (7 more bench recipes), then without them
    XB = [recipe("Skyy_Test_XB%d" % k_, [("Rock_Stone", 1)], "Plant_Fruit_Apple", 1, b_) for k_, b_ in
          enumerate(["Armor_Bench", "Furniture_Bench", "Arcane_Bench", "Farming_Bench", "Builders_Bench", "Alchemy_Bench", "Cooking_Bench"])]
    LIST.extend(XB)
    p_ = one(ev(PK, {"a": "cb:0"}), "FURN2 BENCH the craft panel with more benches")
    cm = cmap(p_) if p_ else {}
    bks_ = [str(x_) for x_ in list(pgF.cbenches)]
    nB_ = len(bks_)
    kC_ = (int(DATA.BW_ALL) - int(DATA.NAVW) - 4) // (int(DATA.TABMIN) + 4) - 3
    sh_ = [k_ for k_ in range(nB_) if ("#SkyyInvBt%d.Text" % k_) in cm]
    K.check(nB_ >= 10 and bks_[-2:] == ["Furnace", "Tannery"] and sh_ == [0] + list(range(1, 1 + kC_)) + [nB_ - 2, nB_ - 1] and sval(cm, "#SkyyInvBtM.Text") == "More"
            and min(wid_(p_, k_) for k_ in sh_) >= 60 and len(sh_) <= 8 and TSEL_ in mk_of(p_, "SkyyInvBt0")
            and sum(wid_(p_, k_) + 4 for k_ in sh_) + int(DATA.NAVW) + 4 <= int(DATA.BW_ALL) + 4,
            "FURN2 BENCH the craft panel: Crafting (selected) + %d benches + More + Furnace + Tanning, >= 60 px each, fits the row (%s %s)" % (kC_, bks_, sh_))
    p_ = one(ev(PK, {"a": "cbm"}), "FURN2 BENCH More on the craft panel")
    sh2_ = [k_ for k_ in range(nB_) if ("#SkyyInvBt%d.Text" % k_) in cmap(p_)]
    K.check(str(pgF.mode) == "c" and sh2_[0] == 0 and sh2_[-2:] == [nB_ - 2, nB_ - 1] and sh2_[1] == 1 + kC_, "FURN2 BENCH More on the craft panel = the next benches (%s)" % sh2_)
    xi_ = sh2_[1]
    p_ = one(ev(PK, {"a": "cb:%d" % xi_}), "FURN2 BENCH a paged bench tab")
    K.check(str(pgF.cbench) == bks_[xi_] and TSEL_ in mk_of(p_, "SkyyInvBt%d" % xi_), "FURN2 BENCH a paged tab opens ITS bench (cb:<index>), selected, its page kept (%s)" % bks_[xi_])
    for x_ in XB:
        LIST.remove(x_)
        ramap.remove(x_)
    pgF.cboff = 0
    p_ = one(ev(PK, {"a": "cb:0"}), "FURN2 BENCH the craft panel again")
    K.check("#SkyyInvBtM.Text" not in cmap(p_) and [str(x_) for x_ in list(pgF.cbenches)][-2:] == ["Furnace", "Tannery"], "FURN2 BENCH fewer benches = every tab, no More")
    one(ev(PK, {"a": "cb:%d" % [str(x_) for x_ in list(pgF.cbenches)].index("Furnace")}), "FURN2 BENCH back to the Furnace panel")
    p_ = one(ev(PK, {"a": "fr:1"}), "INV7 FURN pick Iron Ingot")
    cm = cmap(p_) if p_ else {}
    K.check(str(pgF.fsel) == "Skyy_R_Fe" and FX["lists"][-1] == ("Furnace", "Skyy_R_Fe", "") and sval(cm, "#SkyyInvFxON.Text") == "Iron Ingot"
            and sval(cm, "#SkyyInvFxOS.Text") == "T2 Iron  -  2s each" and sval(cm, "#SkyyInvFxI0.Text") == "Iron Ore  1,262 / 1"
            and sval(cm, "#SkyyInvFb2.Text") == "All 688" and str(sval(cm, "#SkyyInvFr1.Text")).startswith("> "),
            "INV7 FURN pick = the detail (tier, time, inputs have / need), All = min(1,262 can make, 688 free room), the row marked")
    n0_ = nf_()
    p_ = one(ev(PK, {"a": "fb:0"}), "INV7 FURN Queue 1")
    K.check(FX["calls"][n0_:] == [("Furnace", "queue", "Skyy_R_Fe", "1", "ftok1")] and sval(cmap(p_), "#SkyyInvFxMsg.Text") == "queued 1 x Iron Ingot in the Furnace",
            "INV7 FURN 1 = ONE furn queue call (recipe, 1, the list's token), the answer shown")
    p_ = one(ev(PK, {"a": "fb:0"}), "INV7 FURN the same click again")
    K.eq(nf_(), n0_ + 1, "INV7 FURN a double click within 1.5 s = no second queue")
    K.check(str(sval(cmap(p_), "#SkyyInvFxMsg.Text")).startswith("Double click ignored") and "queued 1 x Iron Ingot" in str(sval(cmap(p_), "#SkyyInvFxMsg.Text")),
            "FIX3 the ignored second click is SAID, not silent (%s)" % sval(cmap(p_), "#SkyyInvFxMsg.Text"))
    pgF.lastMoveAt = 0
    one(ev(PK, {"a": "fb:1"}), "INV7 FURN x10")
    pgF.lastMoveAt = 0
    one(ev(PK, {"a": "fb:2"}), "INV7 FURN All")
    K.eq(FX["calls"][n0_ + 1:], [("Furnace", "queue", "Skyy_R_Fe", "10", "ftok1"), ("Furnace", "queue", "Skyy_R_Fe", "all", "ftok1")], "INV7 FURN x10 = 10, All = all")
    one(ev(PK, {"a": "fr:2"}), "INV7 FURN pick the locked Bronze")
    pgF.lastMoveAt = 0
    n0_ = nf_()
    p_ = one(ev(PK, {"a": "fb:2"}), "INV7 FURN All on a locked recipe")
    K.check(nf_() == n0_ and "Not enough materials" in (sval(cmap(p_), "#SkyyInvFxMsg.Text") or ""), "INV7 FURN All with nothing to make = NO call, a hint (%s)" % sval(cmap(p_), "#SkyyInvFxMsg.Text"))
    # the FUEL slot
    p_ = one(ev(PK, {"a": "fxf"}), "INV7 FURN the fuel slot")
    cm = cmap(p_) if p_ else {}
    K.check(bool(pgF.fpick) and sval(cm, "#SkyyInvFr0.Text") == "Oak Log  x1,000" and [sval(cm, "#SkyyInvFb%d.Text" % k_) for k_ in range(3)] == ["64", "All", "Done"]
            and str(sval(cm, "#SkyyInvFxLi.Text")).startswith("Fuel you own"), "INV7 FURN the fuel slot click = the fuel you own in the list, 64 / All / Done")
    n0_ = nf_()
    p_ = one(ev(PK, {"a": "fb:0"}), "INV7 FURN 64 with no fuel picked")
    K.check(nf_() == n0_ and "Pick a fuel" in (sval(cmap(p_), "#SkyyInvFxMsg.Text") or ""), "INV7 FURN 64 with no fuel picked = no call")
    one(ev(PK, {"a": "fr:0"}), "INV7 FURN pick Oak Log")
    FX["ans"]["fuel"] = "+loaded 64 Oak Log into the Furnace"
    pgF.lastMoveAt = 0
    p_ = one(ev(PK, {"a": "fb:0"}), "INV7 FURN load 64")
    K.check(FX["calls"][n0_:] == [("Furnace", "fuel", "Wood_Oak_Trunk", "64", "ftok1")] and not bool(pgF.fpick)
            and sval(cmap(p_), "#SkyyInvFxMsg.Text") == "loaded 64 Oak Log into the Furnace", "INV7 FURN 64 = ONE fuel call (id, 64, token); the list closes on '+'")
    one(ev(PK, {"a": "fxf"}), "INV7 FURN the fuel list again")
    p_ = one(ev(PK, {"a": "fb:2"}), "INV7 FURN Done")
    K.check(not bool(pgF.fpick) and nf_() == n0_ + 1 and sval(cmap(p_), "#SkyyInvFb0.Text") == "1", "INV7 FURN Done closes the fuel list, no call")
    pgF.lastMoveAt = 0
    one(ev(PK, {"a": "fxd", "ItemStackId": "Wood_Oak_Trunk", "ItemStackQuantity": 25}), "INV7 FURN drag fuel onto the slot")
    K.eq(FX["calls"][-1], ("Furnace", "fuel", "Wood_Oak_Trunk", "25", "ftok1"), "INV7 FURN a fuel DRAG onto the slot = ONE fuel call with that id + quantity")
    # Collect all / Cancel / Unload
    FX["ans"]["collect"] = "+Collected 64 items"
    n0_ = nf_()
    p_ = one(ev(PK, {"a": "fxo"}), "INV7 FURN Collect all")
    one(ev(PK, {"a": "fxo"}), "INV7 FURN Collect all again")
    K.check(FX["calls"][n0_:] == [("Furnace", "collect", "", "", "ftok1")] and sval(cmap(p_), "#SkyyInvFxMsg.Text") == "Collected 64 items",
            "INV7 FURN Collect all = ONE collect call; a double click = still one")
    pgF.lastMoveAt = 0
    one(ev(PK, {"a": "fxc"}), "INV7 FURN Cancel")
    pgF.lastMoveAt = 0
    one(ev(PK, {"a": "fxu"}), "INV7 FURN Unload")
    K.eq([c_[1] for c_ in FX["calls"][n0_ + 1:]], ["cancel", "unload"], "INV7 FURN Cancel / Unload = one call each")
    FX["fs"] = "1"
    p_ = one(ev(PK, {"a": "fxr"}), "FIX1 Refresh with enough fuel")
    cm = cmap(p_) if p_ else {}
    K.check(vis_(cm, "FxFnG") and not vis_(cm, "FxFnR") and vis_(cm, "FxNtG") and not vis_(cm, "FxNtR") and not vis_(cm, "FxNt")
            and sval(cm, "#SkyyInvFxNtG.Text") == "Fuel lasts the whole queue", "FIX1 enough fuel = the GREEN fuel line + note")
    FX["fs"] = "0"
    p_ = one(ev(PK, {"a": "fxr"}), "FIX1 Refresh with no fuel state")
    cm = cmap(p_) if p_ else {}
    K.check(vis_(cm, "FxFn") and vis_(cm, "FxNt") and not vis_(cm, "FxFnR") and not vis_(cm, "FxNtG"), "FIX1 no fuel state = the plain lines")
    FX["fs"] = "2"
    # the profile token
    one(ev(PK, {"a": "fr:1"}), "INV7 FURN pick again")
    FX["tok"] = "ftok2"
    p_ = one(ev(PK, {"a": "fxr"}), "INV7 FURN Refresh after a profile switch")
    K.check(pgF.fsel is None and "Your profile changed" in (sval(cmap(p_), "#SkyyInvFxMsg.Text") or "") and str(pgF.fkey) == "ftok2",
            "INV7 FURN a new profile token on a redraw: the pick cleared + said so")
    one(ev(PK, {"a": "fr:1"}), "INV7 FURN pick on the new profile")
    pgF.lastMoveAt = 0
    one(ev(PK, {"a": "fb:0"}), "INV7 FURN queue on the new profile")
    K.eq(FX["calls"][-1], ("Furnace", "queue", "Skyy_R_Fe", "1", "ftok2"), "INV7 FURN the next call carries the NEW token")
    FX["ans"]["queue"] = "-Your profile changed - the Furnace now shows it; nothing was done"
    pgF.lastMoveAt = 0
    p_ = one(ev(PK, {"a": "fb:1"}), "INV7 FURN a '-Your profile changed' answer")
    K.check(pgF.fsel is None and "Your profile changed" in (sval(cmap(p_), "#SkyyInvFxMsg.Text") or ""), "INV7 FURN a '-Your profile changed' answer clears the pick")
    del FX["ans"]["queue"]
    FX["off"] = "Equip a Furnace accessory in your Void Charms to use the Furnace"
    p_ = one(ev(PK, {"a": "fxr"}), "INV7 FURN an off answer")
    K.check(sval(cmap(p_), "#SkyyInvFxS.Text") == FX["off"] and pgF.fkey is None, "INV7 FURN an off answer: the reason shown, no token kept")
    n0_ = nf_()
    pgF.lastMoveAt = 0
    p_ = one(ev(PK, {"a": "fxo"}), "INV7 FURN Collect with no token")
