    K.check(all(len(x) == 8 and x[7] == "0" for x in PW["reads"][1:]) and len(PW["reads"]) >= 4, "TAB2 FIX every later read (redraws after clicks) sends 0 - a pending ask survives its own redraw")
    # SAFE: a stale page token / a double click
