    cm = cmap(pk_[0]) if pk_ else {}
    K.notes.append("TAB5 the screen's first packet: %d commands, %d bindings" % (len(cmds_of(pk_[0])) if pk_ else 0, len(binds_of(pk_[0])) if pk_ else 0))
