    np_.writeFile(hcls)
    E.CM.cmds.put("guild", Ucls.allocateInstance(JClass("skyymenu63.NoPerm").class_))
    BR.put("profile:list:" + uk5, "1:Main:Archer,2:Iron:Warrior,x:Bad:None")
