    # FORT: perk.doubleDropMax 0 / missing = no cap; above 0 = a cap
    SC = JV("StatsCalc")
    HMc = JClass("java.util.HashMap")
    DBLc = JClass("java.lang.Double")
    CFGV = {"perk.doubleDropMax": "0", "perk.mining.doubleDropPerLevel": "0.005"}
